function largestRectangleArea(h) {
  const n = h.length, L = new Array(n), Rr = new Array(n);
  for (let i = 0; i < n; i++) { let j = i - 1; while (j >= 0 && h[j] >= h[i]) j = L[j]; L[i] = j; }
  for (let i = n - 1; i >= 0; i--) { let j = i + 1; while (j < n && h[j] >= h[i]) j = Rr[j]; Rr[i] = j; }
  let best = 0;
  for (let i = 0; i < n; i++) best = Math.max(best, h[i] * (Rr[i] - L[i] - 1));
  return best;
}
